def utc_now():
    return datetime.now(timezone.utc).isoformat()


def q(s: str) -> str:
    return "'" + s.replace("'", "''") + "'"


def parse_args():
    p = argparse.ArgumentParser()
    p.add_argument("--out-root", type=Path, required=True)
    p.add_argument("--threads", type=int, default=8)
    p.add_argument("--memory-limit", default="12GB")
    return p.parse_args()


def paths():
    ps = sorted(PANEL.glob("month=*/analysis_panel.parquet"))
    if len(ps) != 24:
        raise SystemExit(f"Expected 24 monthly Stage 07 Parquets; found {len(ps)}.")
    return ps


def read_expr(ps):
    return "read_parquet([" + ",".join(q(str(x)) for x in ps) + "], union_by_name=true)"


def schema_gate(con, expr):
    d = con.execute(f"DESCRIBE SELECT * FROM {expr} LIMIT 0").fetchdf()
    have = set(d["column_name"].astype(str))
    missing = [x for x in REQ if x not in have]
    if missing:
        raise SystemExit(f"Stage 07 missing required columns: {missing}")


def create_cache(con, expr, cache_path: Path):
    # All sample months are pre-color-advantage. No color adjustment enters E.
    sql = f"""
    COPY (
      WITH src AS (
        SELECT
          chooser_user_id AS chooser,
          CAST(outcome_kind_draw AS DOUBLE) AS kind,
          CAST(engine_eval_cp_disconnected AS DOUBLE) AS eval,
          CAST(chooser_draw_payoff_v2 AS DOUBLE) AS draw_payoff,
          CAST(chooser_win_premium_v2 AS DOUBLE) AS win_premium,
          CAST(chooser_elo AS DOUBLE) AS chooser_elo,
          CAST(disconnected_elo AS DOUBLE) AS opp_elo,
          CAST(chooser_pre_rd_v2 AS DOUBLE) AS chooser_rd,
          CAST(disconnected_pre_rd_v2 AS DOUBLE) AS opp_rd,
          CAST(ply_count AS INTEGER) AS ply,
          CAST(api_speed AS VARCHAR) AS speed,
          CAST(month AS VARCHAR) AS month
        FROM {expr}
        WHERE chooser_user_id IS NOT NULL
          AND outcome_kind_draw IS NOT NULL
          AND engine_eval_cp_disconnected IS NOT NULL
          AND isfinite(engine_eval_cp_disconnected)
          AND chooser_draw_payoff_v2 IS NOT NULL
          AND isfinite(chooser_draw_payoff_v2)
          AND chooser_win_premium_v2 IS NOT NULL
          AND isfinite(chooser_win_premium_v2)
          AND chooser_elo IS NOT NULL
          AND disconnected_elo IS NOT NULL
          AND chooser_pre_rd_v2 IS NOT NULL
          AND disconnected_pre_rd_v2 IS NOT NULL
          AND chooser_pre_rd_v2 > 0
          AND disconnected_pre_rd_v2 > 0
          AND ply_count IS NOT NULL
      ),
      g AS (
        SELECT *,
          (opp_elo - chooser_elo) AS rating_gap,
          chooser_rd / {GLICKO_SCALE} AS phi_i,
          opp_rd / {GLICKO_SCALE} AS phi_j
        FROM src
      ),
      e AS (
        SELECT *,
          1.0 / sqrt(1.0 + 3.0 * phi_j * phi_j / (pi() * pi())) AS g_j
        FROM g
      ),
      z AS (
        SELECT *,
          1.0 / (
            1.0 + exp(
              -g_j * ((chooser_elo - opp_elo) / {GLICKO_SCALE})
            )
          ) AS expected_score
        FROM e
      ),
      k AS (
        SELECT *,
          1.0 / (
            1.0 / (phi_i * phi_i)
            + g_j * g_j * expected_score * (1.0 - expected_score)
          ) AS phi_post_sq
        FROM z
      )
      SELECT
        chooser, kind, eval, draw_payoff, win_premium,
        chooser_elo, opp_elo, chooser_rd, opp_rd, ply, speed, month,
        rating_gap,
        abs(rating_gap) AS abs_rating_gap,
        CASE WHEN rating_gap > 0 THEN 1.0 ELSE 0.0 END AS higher,
        expected_score,
        abs(expected_score - 0.5) AS score_distance,
        {GLICKO_SCALE} * phi_post_sq * g_j AS k_scale,
        ln({GLICKO_SCALE} * phi_post_sq * g_j) AS log_k,
        ({GLICKO_SCALE} * phi_post_sq * g_j) * (0.5 - expected_score) AS predicted_draw_payoff,
        CASE
          WHEN eval >= -600 AND eval < -300 THEN 'm600_m300'
          WHEN eval >= -300 AND eval < -100 THEN 'm300_m100'
          WHEN eval >= -100 AND eval < 100 THEN 'm100_p100'
          WHEN eval >= 100 AND eval < 300 THEN 'p100_p300'
          WHEN eval >= 300 AND eval <= 600 THEN 'p300_p600'
          ELSE NULL
        END AS eval_band,
        CASE
          WHEN ply <= 4 THEN 'p0_4'
          WHEN ply <= 6 THEN 'p5_6'
          WHEN ply <= 8 THEN 'p7_8'
          WHEN ply <= 10 THEN 'p9_10'
          WHEN ply <= 20 THEN 'p11_20'
          WHEN ply <= 40 THEN 'p21_40'
          WHEN ply <= 80 THEN 'p41_80'
          ELSE 'p81p'
        END AS ply_band,
        CASE WHEN month <= '2024-10' THEN 'year1' ELSE 'year2' END AS year_half
      FROM k
    ) TO {q(str(cache_path))}
      (FORMAT PARQUET, COMPRESSION ZSTD, ROW_GROUP_SIZE 250000)
    """
    con.execute(sql)


def mechanical_validation(con, cache: str):
    return con.execute(f"""
      SELECT
        count(*) AS n,
        avg(draw_payoff - predicted_draw_payoff) AS mean_error,
        avg(abs(draw_payoff - predicted_draw_payoff)) AS mae,
        max(abs(draw_payoff - predicted_draw_payoff)) AS max_abs_error,
        corr(draw_payoff, predicted_draw_payoff) AS correlation,
        corr(abs(draw_payoff), abs_rating_gap) AS corr_abs_payoff_abs_gap,
        corr(abs(draw_payoff), score_distance) AS corr_abs_payoff_score_distance,
        corr(abs(draw_payoff), log_k) AS corr_abs_payoff_log_k,
        corr(log_k, chooser_rd) AS corr_logk_chooser_rd,
        corr(log_k, opp_rd) AS corr_logk_opp_rd,
        min(k_scale) AS min_k,
        approx_quantile(k_scale, 0.5) AS median_k,
        max(k_scale) AS max_k
      FROM {cache}
    """).fetchdf()


def broad_rates(con, cache: str):
    rows = []
    for stage, stage_sql in STAGES:
        for eb, ylo, yhi in EVAL_BANDS:
            for gb, glo, ghi in GAP_BUCKETS:
                n, k = con.execute(f"""
                  SELECT count(*), sum(kind)
                  FROM {cache}
                  WHERE eval_band={q(eb)}
                    AND ({stage_sql})
                    AND rating_gap >= {glo} AND rating_gap < {ghi}
                """).fetchone()
                n = int(n or 0); k = int(k or 0)
                p = 100*k/n if n else np.nan
                se = 100*math.sqrt((k/n)*(1-k/n)/n) if n else np.nan
                rows.append(dict(
                    stage=stage, eval_band=eb, gap_bucket=gb,
                    gap_lo=glo, gap_hi=ghi, n=n, kind_draws=k,
                    rate_pct=p, se_pct=se
                ))
    return pd.DataFrame(rows)


def diff(a, b):
    if a is None or b is None or a["n"] == 0 or b["n"] == 0:
        return np.nan, np.nan, np.nan
    d = a["rate_pct"] - b["rate_pct"]
    se = math.sqrt(a["se_pct"]**2 + b["se_pct"]**2)
    return d, se, d/se if se else np.nan


def gap_metrics(rates):
    out=[]
    for (stage,eb),g in rates.groupby(["stage","eval_band"], sort=False):
        d={r["gap_bucket"]:r for r in g.to_dict("records")}
        l=d.get("far_weaker"); c=d.get("near_equal"); r=d.get("far_stronger")
        lc=diff(l,c); rc=diff(r,c); rl=diff(r,l)
        out.append(dict(
            stage=stage, eval_band=eb,
            far_weaker_minus_equal_pp=lc[0],
            far_weaker_minus_equal_se_pp=lc[1],
            far_weaker_minus_equal_z=lc[2],
            far_stronger_minus_equal_pp=rc[0],
            far_stronger_minus_equal_se_pp=rc[1],
            far_stronger_minus_equal_z=rc[2],
            far_stronger_minus_far_weaker_pp=rl[0],
            far_stronger_minus_far_weaker_se_pp=rl[1],
            far_stronger_minus_far_weaker_z=rl[2],
        ))
    return pd.DataFrame(out)


def curves(con, cache: str, axis: str):
    rows=[]
    if axis == "gap":
        lo, hi, nb = -600.0, 600.0, 48
        val = "rating_gap"
    else:
        lo, hi, nb = 0.0, 0.5, 40
        val = "score_distance"
    w=(hi-lo)/nb
    for stage,stage_sql in STAGES:
        for eb,_,_ in EVAL_BANDS:
            for yh in ["all","year1","year2"]:
                ysql="TRUE" if yh=="all" else f"year_half={q(yh)}"
                df=con.execute(f"""
                  WITH b AS (
                    SELECT
                      least({nb-1}, greatest(0,
                        CAST(floor(({val}-CAST({lo} AS DOUBLE))/CAST({w} AS DOUBLE)) AS INTEGER)
                      )) AS bin,
                      kind
                    FROM {cache}
                    WHERE eval_band={q(eb)}
                      AND ({stage_sql})
                      AND ({ysql})
                      AND {val}>={lo} AND {val}<={hi}
                  )
                  SELECT
                    bin,
                    CAST({lo} AS DOUBLE)+(CAST(bin AS DOUBLE)+0.5)*CAST({w} AS DOUBLE) AS x_mid,
                    count(*) AS n,
                    sum(kind) AS kind_draws,
                    100.0*avg(kind) AS rate_pct
                  FROM b
                  GROUP BY bin ORDER BY bin
                """).fetchdf()
                if len(df):
                    df.insert(0,"year_half",yh)
                    df.insert(0,"eval_band",eb)
                    df.insert(0,"stage",stage)
                    rows.append(df)
    return pd.concat(rows,ignore_index=True) if rows else pd.DataFrame()


def krd_descriptives(con, cache: str):
    rows=[]
    for stage,stage_sql in STAGES:
        for eb,_,_ in EVAL_BANDS:
            r=con.execute(f"""
              SELECT
                count(*) n,
                avg(abs_rating_gap) mean_abs_gap,
                approx_quantile(abs_rating_gap,0.5) median_abs_gap,
                avg(score_distance) mean_score_distance,
                avg(k_scale) mean_k,
                approx_quantile(k_scale,0.5) median_k,
                avg(chooser_rd) mean_chooser_rd,
                avg(opp_rd) mean_opp_rd,
                corr(abs_rating_gap,score_distance) corr_gap_score,
                corr(abs_rating_gap,log_k) corr_gap_logk,
                corr(score_distance,log_k) corr_score_logk
              FROM {cache}
              WHERE eval_band={q(eb)} AND ({stage_sql})
            """).fetchdf().iloc[0].to_dict()
            r.update(stage=stage,eval_band=eb)
            rows.append(r)
    return pd.DataFrame(rows)


# ---------- exact one-way chooser-FE OLS with chooser-clustered CR1 ----------

def active_ply_terms(stage: str) -> List[Tuple[str,str]]:
    if stage == "ply_le_10":
        cats=["p0_4","p5_6","p7_8","p9_10"]
    elif stage == "ply_gt_10":
        cats=["p11_20","p21_40","p41_80","p81p"]
    else:
        cats=[x[0] for x in PLY_BANDS]
    # omit first category
    return [(f"ply_{c}", f"CASE WHEN ply_band={q(c)} THEN 1.0 ELSE 0.0 END") for c in cats[1:]]


def common_controls(stage: str):
    terms=[
        ("eval100", "eval/100.0"),
        ("eval100_sq", "(eval/100.0)*(eval/100.0)"),
        ("winprem10", "win_premium/10.0"),
    ]
    terms += active_ply_terms(stage)
    return terms


def model_terms(spec: str, stage: str):
    if spec=="gap":
        key=[
            ("higher","higher"),
            ("abs_gap100","abs_rating_gap/100.0"),
            ("abs_gap100_sq","(abs_rating_gap/100.0)*(abs_rating_gap/100.0)"),
            ("higher_abs_gap100","higher*(abs_rating_gap/100.0)"),
            ("higher_abs_gap100_sq","higher*(abs_rating_gap/100.0)*(abs_rating_gap/100.0)"),
            ("log_k","log_k"),
        ]
    elif spec=="score":
        key=[
            ("higher","higher"),
            ("score10","score_distance*10.0"),
            ("score10_sq","(score_distance*10.0)*(score_distance*10.0)"),
            ("higher_score10","higher*score_distance*10.0"),
            ("higher_score10_sq","higher*(score_distance*10.0)*(score_distance*10.0)"),
            ("log_k","log_k"),
        ]
    elif spec=="horse":
        key=[
            ("higher","higher"),
            ("abs_gap100","abs_rating_gap/100.0"),
            ("higher_abs_gap100","higher*(abs_rating_gap/100.0)"),
            ("score10","score_distance*10.0"),
            ("higher_score10","higher*score_distance*10.0"),
            ("log_k","log_k"),
        ]
    else:
        raise ValueError(spec)
    return key + common_controls(stage)


def stage_filter(stage):
    return dict(STAGES)[stage]


def raw_cross_query(table, filt, terms):
    names=[n for n,_ in terms]
    expr=dict(terms)
    pieces=["count(*) AS n","sum(kind) AS sy","sum(kind*kind) AS syy"]
    for n in names:
        pieces.append(f"sum(({expr[n]})) AS s_{n}")
        pieces.append(f"sum(({expr[n]})*kind) AS sy_{n}")
    for i,a in enumerate(names):
        for b in names[i:]:
            pieces.append(f"sum(({expr[a]})*({expr[b]})) AS s_{a}__{b}")
    return f"SELECT {','.join(pieces)} FROM {table} WHERE {filt}"


def create_cluster_sums(con, table, filt, terms, name):
    expr=dict(terms)
    pieces=["chooser","count(*) AS n","sum(kind) AS sy"]
    for n,e in terms:
        pieces.append(f"sum(({e})) AS s_{n}")
    con.execute(f"CREATE OR REPLACE TEMP TABLE {name} AS SELECT {','.join(pieces)} FROM {table} WHERE {filt} GROUP BY chooser")


def correction_query(name, terms):
    names=[n for n,_ in terms]
    pieces=["count(*) AS clusters","sum(n) AS n"]
    for n in names:
        pieces.append(f"sum(s_{n}*sy/n) AS cy_{n}")
    for i,a in enumerate(names):
        for b in names[i:]:
            pieces.append(f"sum(s_{a}*s_{b}/n) AS c_{a}__{b}")
    return f"SELECT {','.join(pieces)} FROM {name}"


def fit_fe(con, table, filt, terms, model_id):
    names=[n for n,_ in terms]
    expr=dict(terms)
    t0=time.time()
    sums_name="cs_" + str(abs(hash(model_id)) % 10_000_000)

    raw=con.execute(raw_cross_query(table,filt,terms)).fetchdf().iloc[0].to_dict()
    create_cluster_sums(con,table,filt,terms,sums_name)
    corr=con.execute(correction_query(sums_name,terms)).fetchdf().iloc[0].to_dict()

    p=len(names)
    XX=np.zeros((p,p),float)
    Xy=np.zeros(p,float)
    for i,a in enumerate(names):
        Xy[i]=float(raw[f"sy_{a}"] or 0)-float(corr[f"cy_{a}"] or 0)
        for j,b in enumerate(names[i:],start=i):
            key=f"s_{a}__{b}"
            ckey=f"c_{a}__{b}"
            v=float(raw[key] or 0)-float(corr[ckey] or 0)
            XX[i,j]=XX[j,i]=v

    diag=np.diag(XX)
    keep=diag > max(1e-10, np.nanmax(diag)*1e-14)
    kept=[names[i] for i in range(p) if keep[i]]
    if not any(keep):
        raise RuntimeError(f"{model_id}: no within-chooser identifying variation")

    XXk=XX[np.ix_(keep,keep)]
    Xyk=Xy[keep]
    rank=int(np.linalg.matrix_rank(XXk))
    beta=np.linalg.pinv(XXk,rcond=1e-11)@Xyk
    cond=float(np.linalg.cond(XXk)) if rank==XXk.shape[0] else float("inf")

    # cluster scores in a second pass.
    kept_terms=[(n,expr[n]) for n in kept]
    beta_map={n:float(beta[i]) for i,n in enumerate(kept)}
    mean_terms={n:f"(s.s_{n}/s.n)" for n in kept}
    resid="(c.kind - s.sy/s.n"
    for n,e in kept_terms:
        resid += f" - ({beta_map[n]})*(({e})-{mean_terms[n]})"
    resid += ")"

    score_cols=[]
    for n,e in kept_terms:
        score_cols.append(f"sum((({e})-{mean_terms[n]})*{resid}) AS sc_{n}")

    meat_parts=[]
    for i,a in enumerate(kept):
        for b in kept[i:]:
            meat_parts.append(f"sum(sc_{a}*sc_{b}) AS m_{a}__{b}")

    meat_sql=f"""
      WITH scores AS (
        SELECT c.chooser, {','.join(score_cols)}
        FROM {table} c
        JOIN {sums_name} s USING (chooser)
        WHERE {filt}
        GROUP BY c.chooser
      )
      SELECT {','.join(meat_parts)} FROM scores
    """
    mrow=con.execute(meat_sql).fetchdf().iloc[0].to_dict()
    M=np.zeros((len(kept),len(kept)),float)
    for i,a in enumerate(kept):
        for j,b in enumerate(kept[i:],start=i):
            v=float(mrow[f"m_{a}__{b}"] or 0)
            M[i,j]=M[j,i]=v

    inv=np.linalg.pinv(XXk,rcond=1e-11)
    G=int(corr["clusters"])
    cr1=(G/(G-1)) if G>1 else 1.0
    V=cr1*(inv@M@inv)
    se=np.sqrt(np.maximum(0,np.diag(V)))

    coefs=[]
    for i,n in enumerate(kept):
        b=float(beta[i]); s=float(se[i])
        coefs.append(dict(
            model_id=model_id, term=n, coef_pp=100*b, se_pp=100*s,
            z=b/s if s>0 else np.nan
        ))

    receipt=dict(
        model_id=model_id,
        rows=int(raw["n"]),
        clusters=G,
        terms_requested=p,
        terms_kept=len(kept),
        rank=rank,
        condition_number=cond,
        runtime_seconds=time.time()-t0,
        dropped_terms=";".join([names[i] for i in range(p) if not keep[i]])
    )
    con.execute(f"DROP TABLE IF EXISTS {sums_name}")
    return coefs,receipt


def fe_models(con, cache: str):
    coeffs=[]; receipts=[]
    for stage,_ in STAGES:
        for eb,_,_ in EVAL_BANDS:
            base=f"eval_band={q(eb)} AND ({stage_filter(stage)}) AND abs_rating_gap<=600"
            for spec in ["gap","score"]:
                mid=f"{spec}__{stage}__{eb}"
                c,r=fit_fe(con,cache,base,model_terms(spec,stage),mid)
                coeffs.extend(c); receipts.append(r)
    # horse race only where the visual U is most important and support strongest.
    for stage in ["all","ply_gt_10"]:
        for eb in ["m100_p100","p100_p300","p300_p600"]:
            base=f"eval_band={q(eb)} AND ({stage_filter(stage)}) AND abs_rating_gap<=600"
            mid=f"horse__{stage}__{eb}"
            c,r=fit_fe(con,cache,base,model_terms("horse",stage),mid)
            coeffs.extend(c); receipts.append(r)
    return pd.DataFrame(coeffs),pd.DataFrame(receipts)


def band_contrasts(coefs):
    # Convert model coefficients into intuitive fitted changes from equality to
    # 300 Elo distance on each side, holding other terms fixed.
    rows=[]
    for mid,g in coefs.groupby("model_id",sort=False):
        d={r.term:r for r in g.itertuples()}
        spec=mid.split("__")[0]
        if spec=="gap" and all(x in d for x in ["abs_gap100","abs_gap100_sq","higher_abs_gap100","higher_abs_gap100_sq","higher"]):
            x=3.0
            left=d["abs_gap100"].coef_pp*x+d["abs_gap100_sq"].coef_pp*x*x
            right=(d["higher"].coef_pp
                   +(d["abs_gap100"].coef_pp+d["higher_abs_gap100"].coef_pp)*x
                   +(d["abs_gap100_sq"].coef_pp+d["higher_abs_gap100_sq"].coef_pp)*x*x)
            rows.append(dict(model_id=mid,metric="predicted_change_equal_to_300_weaker_pp",value=left))
            rows.append(dict(model_id=mid,metric="predicted_change_equal_to_300_stronger_pp",value=right))
            rows.append(dict(model_id=mid,metric="right_minus_left_at_300_pp",value=right-left))
        if spec=="score" and all(x in d for x in ["score10","score10_sq","higher_score10","higher_score10_sq","higher"]):
            # score_distance 0.20 -> score10=2.
            x=2.0
            left=d["score10"].coef_pp*x+d["score10_sq"].coef_pp*x*x
            right=(d["higher"].coef_pp
                   +(d["score10"].coef_pp+d["higher_score10"].coef_pp)*x
                   +(d["score10_sq"].coef_pp+d["higher_score10_sq"].coef_pp)*x*x)
            rows.append(dict(model_id=mid,metric="predicted_change_equal_to_score_distance_0p20_weaker_pp",value=left))
            rows.append(dict(model_id=mid,metric="predicted_change_equal_to_score_distance_0p20_stronger_pp",value=right))
            rows.append(dict(model_id=mid,metric="right_minus_left_at_score_distance_0p20_pp",value=right-left))
    return pd.DataFrame(rows)


def main():
    a=parse_args()
    if a.out_root.exists():
        raise SystemExit(f"Refusing to overwrite {a.out_root}")
    a.out_root.mkdir(parents=True)
    private=a.out_root/"private_cache"
    private.mkdir()
    cache_path=private/"rating_gap_krd_derived_private.parquet"

    ps=paths()
    expr=read_expr(ps)
    con=duckdb.connect(":memory:")
    con.execute(f"SET threads={a.threads}")
    con.execute(f"SET memory_limit={q(a.memory_limit)}")
    con.execute("SET preserve_insertion_order=false")
    schema_gate(con,expr)

    n=int(con.execute(f"SELECT count(*) FROM {expr}").fetchone()[0])
    months=int(con.execute(f"SELECT count(DISTINCT month) FROM {expr}").fetchone()[0])
    if n!=EXPECTED_ROWS or months!=EXPECTED_MONTHS:
        raise SystemExit(f"Authority authentication failed: rows={n:,}, months={months}")

    print("STAGE07_AUTHENTICATED_OK", n, months, flush=True)
    create_cache(con,expr,cache_path)
    cache=f"read_parquet({q(str(cache_path))})"

    val=mechanical_validation(con,cache)
    val.to_csv(a.out_root/"mechanical_validation.csv",index=False)
    print("MECHANICAL_VALIDATION", val.to_dict("records")[0], flush=True)

    rates=broad_rates(con,cache)
    rates.to_csv(a.out_root/"rating_gap_broad_rates.csv",index=False)
    gap_metrics(rates).to_csv(a.out_root/"rating_gap_u_metrics.csv",index=False)

    curves(con,cache,"gap").to_csv(a.out_root/"rating_gap_curves.csv",index=False)
    curves(con,cache,"score").to_csv(a.out_root/"expected_score_curves.csv",index=False)
    krd_descriptives(con,cache).to_csv(a.out_root/"krd_descriptives.csv",index=False)

    coefs,receipts=fe_models(con,cache)
    coefs.to_csv(a.out_root/"fe_model_coefficients.csv",index=False)
    receipts.to_csv(a.out_root/"fe_model_receipts.csv",index=False)
    band_contrasts(coefs).to_csv(a.out_root/"fe_model_band_contrasts.csv",index=False)
    con.close()

    settings={
      "status":"RATING_GAP_KRD_DECOMPOSITION_OK",
      "created_utc":utc_now(),
      "authority":{"panel":str(PANEL),"rows":n,"months":months,"engine":"Stockfish 18 nodes=100,000"},
      "scientific_status":"exploratory diagnostic prompted by observed 3D surface; not confirmatory",
      "rating_gap_definition":"disconnected_elo - chooser_elo; positive means disconnected opponent higher-rated",
      "glicko_scale":GLICKO_SCALE,
      "board_eval_bands":EVAL_BANDS,
      "rating_gap_buckets":GAP_BUCKETS,
      "stages":[x[0] for x in STAGES],
      "software":{"python":sys.version,"duckdb":duckdb.__version__,"numpy":np.__version__,"pandas":pd.__version__,"platform":platform.platform()},
      "private_cache":str(cache_path),
      "privacy":"private cache contains chooser identifiers and must not be committed or uploaded; public CSV outputs contain aggregates/model coefficients only."
    }
    (a.out_root/"settings.json").write_text(json.dumps(settings,indent=2)+"\n")

    print("RATING_GAP_KRD_DECOMPOSITION_OK")
    print("Output root:",a.out_root)


if __name__=="__main__":
    main()
